INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-0Lgx1LQndr9eLBVLu1Rt', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '저도 될까요?', '방명록이니까 아무나 써도 될 것 같은데...', '2025-04-21 02:32:44', '2025-04-21 02:32:44');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-ShavGOs4qXzsoozoPOq4', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '네 아무나 작성할 수 있습니다.', '기본적으로는 누구나 구글 로그인하면 쓸 수 있도록 되어 있습니다. 조금만 다듬으면 주인장만 보고 쓸 수 있는 일기장이 될 수도 있고, 누구나 볼 수 있지만 주인장만 쓸 수 있는 마이크로 블로그가 될 수도 있습니다.', '2025-04-21 02:34:53', '2025-04-21 02:34:53');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-Q7aL5bbeHqEuWUTk1gYF', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '파이어베이스 프로젝트 시작하면', '본인 apiKey같은거 알려주는 박스나오는데 거기만 복사해다 갈아치기하면  됩니다. 그리고 소스 입맞에 맞게 적당히 고치셔서 깃허브에 올려서 만드시구요.', '2025-04-21 02:44:36', '2025-04-21 02:44:36');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-VsTTeYXUIWmKGNmgoxI9', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '그냥 조만간에 유튜브 올리니까', '그거봐요', '2025-04-21 02:45:15', '2025-04-21 02:45:15');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-4XWqXGDlgXxohH0dvBbO', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '테스트하고 있으니', '뭐라도 한 줄 쓰고 가요.', '2025-04-21 02:57:45', '2025-04-21 02:57:45');
