INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-Iiq3Te95Vtkf1rIphoMM', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '하쿠센세 ☕︎', '즐거운 봄날 오후 보내세요 ☺︎', '2025-04-21 06:05:05', '2025-04-21 06:05:05');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-4pcwtFL8JpMQiFzrpWPY', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '고오맙습니다.', '결국 마감하는데 하루가 꼬박걸렸다. 계속 고칠 수 있다는 점이 단점이다. 끝이 안난다. 말은 방명록이지만 그냥 내 일기가 될 듯.', '2025-04-21 09:57:14', '2025-04-21 09:57:14');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-1ZR5BSN3h1uL9GcklisN', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '야마닌 블로그', 'yamanin.kr 여행기 간명하게 잘 쓰심. 구구절절이 쓸데없는 말 일절없음. ', '2025-04-21 11:04:49', '2025-04-21 11:04:49');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-8kjD3ZAYKU5sxa9ZtIG9', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '섬어', '그 해 나의 말은 너에게 닿았습니다.
그러니 이제 그 말은 나와 가장 멀어진 셈입니다. - 박준(마중도 배웅도 없이)
', '2025-04-21 11:09:45', '2025-04-21 11:09:45');
INSERT OR IGNORE INTO entries (id, user_id, entry_date, title, body, created_at, updated_at) VALUES ('verse-2BAPtHAmEVmP5SA7oxeZ', (SELECT id FROM users ORDER BY created_at, rowid LIMIT 1), '2025-04-21', '학씨사마', '흔또니 익게가 아니데스요? 
